 1	/**
 2	 * Notes Collected View — Repo Parallelizer GUI.
 3	 *
 4	 * Two-panel layout:
 5	 *   - Left sidebar: all workspaces grouped by project (collapsible groups).
 6	 *     Workspaces with existing notes are visually distinguished with a
 7	 *     `.has-notes` class on the sidebar item.
 8	 *   - Right main panel: editable note cards for workspaces with non-empty notes.
 9	 *     On initial load only non-empty note cards are rendered.
10	 *     Clicking a sidebar item for a workspace with a card scrolls to it.
11	 *     Clicking a sidebar item for a workspace without a card creates a new
12	 *     empty card and focuses the textarea.
13	 *     Each card auto-saves after 1000 ms of inactivity (debounce).
14	 *     Saving an empty note removes the card and clears the sidebar indicator.
15	 *
16	 * Data flow:
17	 *   1. `api.notes.list()` fetches the raw PascalCase `GET /api/notes` response.
18	 *   2. `normaliseNotesResponse()` converts it to a camelCase
19	 *      `{ projects: [{ projectId, projectName, workspaces: [{ workspaceId, notes }] }] }`
20	 *      structure used throughout the view.
21	 *   3. A `notesMap` (`Map<"${projectId}|${workspaceId}", string>`) mirrors the
22	 *      current note text in memory, keeping sidebar indicators and newly-created
23	 *      cards in sync with saves without re-fetching from the server.
24	 *
25	 * All dynamic text is set via `textContent` (never `innerHTML`) for XSS safety.
26	 *
27	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
28	 * @param {Object}      _params   - Route params (none for this route).
29	 */
30	
31	import { api }                    from '../api.js';
32	import { showToast }              from '../components/toast.js';
33	import { normaliseNotesResponse } from '../utils/normalise.js';
34	
35	// ---------------------------------------------------------------------------
36	// Internal DOM helpers
37	// ---------------------------------------------------------------------------
38	
39	/**
40	 * Find a note card in the main panel by project + workspace ID using dataset
41	 * attributes (avoids CSS-escaping concerns with arbitrary ID strings).
42	 *
43	 * @param {HTMLElement} mainPanel
44	 * @param {string}      projectId
45	 * @param {string}      workspaceId
46	 * @returns {HTMLElement|null}
47	 */
48	function findCard(mainPanel, projectId, workspaceId) {
49	    for (const card of mainPanel.querySelectorAll('.notes-card')) {
50	        if (card.dataset.projectId === projectId && card.dataset.workspaceId === workspaceId) {
51	            return card;
52	        }
53	    }
54	    return null;
55	}
56	
57	/**
58	 * Find a sidebar list item by project + workspace ID.
59	 *
60	 * @param {HTMLElement} sidebar
61	 * @param {string}      projectId
62	 * @param {string}      workspaceId
63	 * @returns {HTMLElement|null}
64	 */
65	function findSidebarItem(sidebar, projectId, workspaceId) {
66	    for (const item of sidebar.querySelectorAll('.notes-sidebar-item')) {
67	        if (item.dataset.projectId === projectId && item.dataset.workspaceId === workspaceId) {
68	            return item;
69	        }
70	    }
71	    return null;
72	}
73	
74	// ---------------------------------------------------------------------------
75	// Empty-state management
76	// ---------------------------------------------------------------------------
77	
78	/**
79	 * Show or hide the "no notes" empty-state message based on whether the main
80	 * panel contains any note cards.
81	 *
82	 * @param {HTMLElement} mainPanel
83	 */
84	function refreshEmptyState(mainPanel) {
85	    const existing = mainPanel.querySelector('.notes-empty-state');
86	    const hasCards = mainPanel.querySelector('.notes-card') !== null;
87	    if (hasCards && existing) {
88	        existing.remove();
89	    } else if (!hasCards && !existing) {
90	        const p = document.createElement('p');
91	        p.className = 'notes-empty-state';
92	        p.textContent = 'No workspace notes yet. Click a workspace in the sidebar to add one.';
93	        mainPanel.appendChild(p);
94	    }
95	}
96	
97	// ---------------------------------------------------------------------------
98	// Sidebar builder
99	// ---------------------------------------------------------------------------

251	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
252	 * @param {Object}      _params   - Route params (none for this route).
253	 */
254	export async function renderNotesCollected(container, _params) {
255	    // Show loading state immediately.
256	    const loadingEl = document.createElement('p');
257	    loadingEl.className = 'notes-loading';
258	    loadingEl.textContent = 'Loading notes\u2026';
259	    container.appendChild(loadingEl);
260	
261	    let rawResponse;
262	    let displaySettings;
263	    try {
264	        [rawResponse, displaySettings] = await Promise.all([
265	            api.notes.list(),
266	            api.config.notesDisplay.get().catch(() => ({})),
267	        ]);
268	    } catch (err) {
269	        container.removeChild(loadingEl);
270	        showToast(`Failed to load notes: ${err.message}`, 'error');
271	        const errEl = document.createElement('p');
272	        errEl.className = 'notes-error';
273	        errEl.textContent = 'Could not load workspace notes. Please try again.';
274	        container.appendChild(errEl);
275	        return;
276	    }
277	
278	    container.removeChild(loadingEl);
279	
280	    const { projects } = normaliseNotesResponse(rawResponse);
281	
282	    // ---- In-memory notes map — keeps local state in sync with saves ----
283	    /** @type {Map<string, string>} Key: `${projectId}|${workspaceId}` */
284	    const notesMap = new Map();
285	    for (const project of projects) {
286	        for (const ws of project.workspaces) {
287	            notesMap.set(`${project.projectId}|${ws.workspaceId}`, ws.notes);
288	        }
289	    }
290	
291	    // ---- Layout container ----
292	    const layout = document.createElement('div');
293	    layout.className = 'notes-view';
294	
295	    // ---- Main panel ----
296	    const mainPanel = document.createElement('div');
297	    mainPanel.className = 'notes-main';
298	
299	    // Apply display settings from API (gracefully degrade if fetch failed).
300	    if (displaySettings.notesColumns) {
301	        mainPanel.style.gridTemplateColumns = `repeat(${displaySettings.notesColumns}, 1fr)`;
302	    }
303	    if (displaySettings.notesCardHeight) {
304	        mainPanel.style.setProperty('--notes-card-height', `${displaySettings.notesCardHeight}px`);
305	    }
306	
307	    // Forward-declare sidebar so handlers can reference it after assignment.
308	    /** @type {HTMLElement} */
309	    let sidebar; // assigned below after handlers are defined
310	
311	    // ---- Shared save handler ----
312	    async function handleSave(projectId, workspaceId, notes) {
313	        await api.workspaces.update(projectId, workspaceId, { notes });
314	        notesMap.set(`${projectId}|${workspaceId}`, notes);
315	        // Update sidebar indicator for non-empty saves.
316	        if (notes) {
317	            findSidebarItem(sidebar, projectId, workspaceId)?.classList.add('has-notes');
318	        }
319	    }
320	
321	    // ---- Handler: note saved as empty → remove card + clear sidebar indicator ----
322	    function handleCardEmpty(projectId, workspaceId) {
323	        const card = findCard(mainPanel, projectId, workspaceId);
324	        if (card) card.remove();
325	
326	        findSidebarItem(sidebar, projectId, workspaceId)?.classList.remove('has-notes');
327	        notesMap.set(`${projectId}|${workspaceId}`, '');
328	        refreshEmptyState(mainPanel);
329	    }

330	
331	    // ---- Sidebar click handler ----
332	    function handleSidebarClick(projectId, workspaceId) {
333	        const existingCard = findCard(mainPanel, projectId, workspaceId);
334	        if (existingCard) {
335	            // Card already exists — scroll to it and focus.
336	            existingCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
337	            existingCard.querySelector('.notes-card-textarea')?.focus();
338	            return;
339	        }
340	
341	        // No card yet — create a new empty one.
342	        const project = projects.find((p) => p.projectId === projectId);
