165	/**
166	 * Build a single editable note card for a workspace.
167	 *
168	 * The card header contains a clickable link to the workspace detail view.
169	 * The textarea fires a 1000 ms debounced save on `input` events.
170	 * A status span (aria-live="polite") shows Saving… / Saved / Save failed.
171	 *
172	 * @param {string}   projectId
173	 * @param {string}   projectName
174	 * @param {string}   workspaceId
175	 * @param {string}   initialNotes
176	 * @param {function(string, string, string): Promise<void>} onSave
177	 *   Called with (projectId, workspaceId, notes). Rejects on save failure.
178	 * @param {function(): void} onEmpty
179	 *   Called (after a successful save) when the note text is empty.
180	 * @returns {HTMLElement}
181	 */
182	function buildNoteCard(projectId, projectName, workspaceId, initialNotes, onSave, onEmpty) {
183	    const article = document.createElement('article');
184	    article.className = 'notes-card';
185	    article.dataset.projectId   = projectId;
186	    article.dataset.workspaceId = workspaceId;
187	
188	    // ---- Card header ----
189	    const header = document.createElement('header');
190	    header.className = 'notes-card-header';
191	
192	    const link = document.createElement('a');
193	    link.href = `#/projects/${encodeURIComponent(projectId)}/workspaces/${encodeURIComponent(workspaceId)}`;
194	    link.className = 'notes-card-ws-link';
195	    // textContent used intentionally: projectName/workspaceId come from the
196	    // server response and must not be treated as markup.
197	    link.textContent = `${projectName || projectId} \u203a ${workspaceId}`;
198	    header.appendChild(link);
199	
200	    const statusEl = document.createElement('span');
201	    statusEl.className = 'notes-card-status';
202	    statusEl.setAttribute('aria-live', 'polite');
203	    statusEl.hidden = true;
204	    header.appendChild(statusEl);
205	
206	    article.appendChild(header);
207	
208	    // ---- Textarea ----
209	    const textarea = document.createElement('textarea');
210	    textarea.className = 'notes-card-textarea';
211	    textarea.value = initialNotes;
212	    textarea.rows = 6;
213	    article.appendChild(textarea);
214	
215	    // ---- Debounced auto-save ----
216	    let debounceTimer = null;
217	
218	    textarea.addEventListener('input', () => {
219	        clearTimeout(debounceTimer);
220	        debounceTimer = setTimeout(async () => {
221	            statusEl.textContent = 'Saving\u2026';
222	            statusEl.hidden = false;
223	            try {
224	                await onSave(projectId, workspaceId, textarea.value);
225	                if (textarea.value === '') {
226	                    onEmpty();
227	                    return;
228	                }
229	                statusEl.textContent = 'Saved';
230	                setTimeout(() => { statusEl.hidden = true; }, 3000);
231	            } catch {
232	                statusEl.textContent = 'Save failed.';
233	            }
234	        }, 1000);
235	    });
236	
237	    return article;
238	}
